import { Hono } from 'hono';
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { WebStandardStreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js';

const app = new Hono();

// POST only. A stateless transport handles exactly ONE request, so build both per request.
app.post('/mcp', async (c) => {
  const server = buildServer();                 // fresh low-level Server; connect() binds 1:1
  const transport = new WebStandardStreamableHTTPServerTransport({
    sessionIdGenerator: undefined,              // stateless: no Mcp-Session-Id, no session validation
    enableJsonResponse: true                    // buffered single JSON object -> safe to close immediately
  });
  await server.connect(transport);
  const res = await transport.handleRequest(c.req.raw);   // c.req.raw, the Web Request - not c.req
  await transport.close();
  await server.close();
  return res;                                   // body already buffered; closing did not truncate it
});

// The transport does NOT 405 a GET - it opens an SSE stream that never ends. Answer it ourselves.
// The SDK client handles 405 here natively (client/streamableHttp.js:101).
app.all('/mcp', (c) =>
  c.json({ jsonrpc: '2.0', error: { code: -32000, message: 'Method not allowed.' }, id: null },
         405, { Allow: 'POST' }));
```
